        float3 getpoint(float2 id){
                float EVO = (autop>0.5)? PROGRESS+(time*1.5) : PROGRESS;
         float3 r=rand3(id);
         float3 ou=float3(
          sin(EVO*r.x),
          cos(EVO*r.y),
          sin(EVO*r.z*10.)
         );
         return ou*0.45+0.5;
        }
        float line(float2 uv, float2 p, float2 p2){
         float2 n=uv-p;
         float2 w=p2-p;
         float r=clamp(dot(n,w)/dot(w,w),0.,1.);
         r=length(n-w*r);
               return clamp(smoothstep(0.04,0.01,r)*(smoothstep(0.6,1.,1./distance(p,p2))),0.,1.);
        }
        float N21(float2 p)
        {
            p = fract(p*float2(651.34, 237.73));
            p += dot(p, p + 23.45);
            return fract(p.x*p.y);
        }
        float2 N22(float2 p)
        {
            float n = N21(p);
            return float2(n, N21(p+n));
        }
        float2 GetGridPoint(float2 id, float2 offs)
        {
            float EVOX = (autop>0.5)? PROGRESS+(time*1.5) : PROGRESS;
            float2 n = N22(id + offs) * EVOX;
            return offs + sin(n) * .3;
        }
        float DistToLine(float2 p, float2 a, float2 b)
        {
            float2 pa = p-a;
            float2 ba = b-a;
            float t = clamp(dot(pa, ba)/dot(ba,ba),0.,1.);
            return length(pa - ba*t);
        }
        float LineX(float2 p, float2 a, float2 b)
        {
            float d = DistToLine(p, a, b);
            float m = smoothstep(.05, .005, d);
            m *= smoothstep(1.1, .6, length(a - b));
            return m;
        }
